import 'package:flutter/material.dart';
import 'package:flutter_staggered_grid_view/flutter_staggered_grid_view.dart';
import 'dart:math';

class MasonryExample extends StatelessWidget {
  const MasonryExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Masonry Grid')),
      body: MasonryGridView.count(
        crossAxisCount: 2, // 열 수
        mainAxisSpacing: 8, // 세로 간격
        crossAxisSpacing: 8, // 가로 간격
        padding: const EdgeInsets.all(8),
        itemCount: 20,
        itemBuilder: (context, index) {
          // 랜덤한 높이의 카드 생성
          final height = 100.0 + Random().nextInt(100);
          return _GridItem(
            index: index,
            height: height,
          );
        },
      ),
    );
  }
}

class _GridItem extends StatelessWidget {
  final int index;
  final double height;

  const _GridItem({required this.index, required this.height});

  @override
  Widget build(BuildContext context) {
    return Container(
      height: height,
      decoration: BoxDecoration(
        color: Colors.primaries[index % Colors.primaries.length],
        borderRadius: BorderRadius.circular(12),
      ),
      child: Center(
        child: Text(
          'Item $index',
          style: const TextStyle(
            color: Colors.white,
            fontWeight: FontWeight.bold,
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_staggered_grid_view/flutter_staggered_grid_view.dart';

class ImageGalleryExample extends StatelessWidget {
  const ImageGalleryExample({super.key});

  // 샘플 이미지 데이터 (실제로는 API에서 가져옴)
  static const List<Map<String, dynamic>> _images = [
    {'url': 'https://picsum.photos/200/300', 'aspectRatio': 0.67},
    {'url': 'https://picsum.photos/200/200', 'aspectRatio': 1.0},
    {'url': 'https://picsum.photos/200/250', 'aspectRatio': 0.8},
    {'url': 'https://picsum.photos/200/350', 'aspectRatio': 0.57},
    {'url': 'https://picsum.photos/200/180', 'aspectRatio': 1.11},
    {'url': 'https://picsum.photos/200/280', 'aspectRatio': 0.71},
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('이미지 갤러리')),
      body: MasonryGridView.builder(
        crossAxisCount: 2,
        mainAxisSpacing: 8,
        crossAxisSpacing: 8,
        padding: const EdgeInsets.all(8),
        itemCount: _images.length * 5, // 반복해서 표시
        itemBuilder: (context, index) {
          final image = _images[index % _images.length];
          return _ImageCard(
            imageUrl: '${image['url']}?random=$index',
            aspectRatio: image['aspectRatio'] as double,
            index: index,
          );
        },
      ),
    );
  }
}

class _ImageCard extends StatelessWidget {
  final String imageUrl;
  final double aspectRatio;
  final int index;

  const _ImageCard({
    required this.imageUrl,
    required this.aspectRatio,
    required this.index,
  });

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: () {
        // 이미지 상세 보기
      },
      child: ClipRRect(
        borderRadius: BorderRadius.circular(12),
        child: AspectRatio(
          aspectRatio: aspectRatio,
          child: Stack(
            fit: StackFit.expand,
            children: [
              Image.network(
                imageUrl,
                fit: BoxFit.cover,
                loadingBuilder: (context, child, loadingProgress) {
                  if (loadingProgress == null) return child;
                  return Container(
                    color: Colors.grey[200],
                    child: const Center(
                      child: CircularProgressIndicator(),
                    ),
                  );
                },
                errorBuilder: (context, error, stackTrace) {
                  return Container(
                    color: Colors.grey[300],
                    child: const Icon(Icons.error),
                  );
                },
              ),
              // 하단 그라데이션 오버레이
              Positioned(
                bottom: 0,
                left: 0,
                right: 0,
                child: Container(
                  padding: const EdgeInsets.all(8),
                  decoration: BoxDecoration(
                    gradient: LinearGradient(
                      begin: Alignment.bottomCenter,
                      end: Alignment.topCenter,
                      colors: [
                        Colors.black.withOpacity(0.7),
                        Colors.transparent,
                      ],
                    ),
                  ),
                  child: Text(
                    'Photo $index',
                    style: const TextStyle(
                      color: Colors.white,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

