// Quilted: 특정 패턴으로 타일 배치
class _QuiltedGridExample extends StatelessWidget {
  const _QuiltedGridExample();

  @override
  Widget build(BuildContext context) {
    return GridView.custom(
      padding: const EdgeInsets.all(8),
      gridDelegate: SliverQuiltedGridDelegate(
        crossAxisCount: 4,
        mainAxisSpacing: 8,
        crossAxisSpacing: 8,
        repeatPattern: QuiltedGridRepeatPattern.inverted,
        pattern: [
          const QuiltedGridTile(2, 2), // 2x2 큰 타일
          const QuiltedGridTile(1, 1), // 1x1 작은 타일
          const QuiltedGridTile(1, 1),
          const QuiltedGridTile(1, 2), // 1x2 세로 타일
        ],
      ),
      childrenDelegate: SliverChildBuilderDelegate(
        (context, index) => _ColorTile(index: index),
        childCount: 20,
      ),
    );
  }
}

// Staired: 계단 형태로 배치
class _StairedGridExample extends StatelessWidget {
  const _StairedGridExample();

  @override
