      padding: const EdgeInsets.all(8),
      gridDelegate: SliverStairedGridDelegate(
        crossAxisSpacing: 8,
        mainAxisSpacing: 8,
        pattern: [
          const StairedGridTile(0.5, 1), // 비율, 높이 배수
          const StairedGridTile(0.5, 0.8),
          const StairedGridTile(0.5, 1.2),
